   "flashcards": [
    {
     "unit": 1,
     "front": "$\\lim_{x\\to0}\\frac{\\sin x}{x}$ and $\\lim_{x\\to0}\\frac{1-\\cos x}{x}$",
     "back": "$1$ and $0$"
    },
    {
     "unit": 1,
     "front": "Horizontal asymptotes of a rational function",
     "back": "Degree of top < bottom: $y=0$. Equal degrees: ratio of leading coefficients. Top > bottom: no horizontal asymptote."
    },
    {
     "unit": 1,
     "front": "Three types of discontinuity",
     "back": "Removable (a hole: the limit exists but $\\ne f(a)$), jump (the one-sided limits differ), and infinite (a vertical asymptote)."
    },
    {
     "unit": 1,
     "front": "Squeeze Theorem",
     "back": "If $g\\le f\\le h$ near $a$ and $\\lim g=\\lim h=L$, then $\\lim f=L$."
    },
    {
     "unit": 2,
     "front": "Power, product, and quotient rules",
     "back": "$(x^n)'=nx^{n-1}$, $\\;(uv)'=u'v+uv'$, $\\;\\left(\\frac uv\\right)'=\\frac{u'v-uv'}{v^2}$"
    },
    {
     "unit": 2,
     "front": "Differentiable implies…",
     "back": "Continuous. The converse is false: $|x|$ is continuous at $0$ but not differentiable there."
    },
    {
     "unit": 2,
     "front": "$\\frac{d}{dx}e^x$, $\\frac{d}{dx}\\ln x$, $\\frac{d}{dx}a^x$",
     "back": "$e^x$, $\\;\\frac1x$, $\\;a^x\\ln a$"
    },
    {
     "unit": 3,
     "front": "Chain rule",
     "back": "$\\frac{d}{dx}f(g(x))=f'(g(x))\\,g'(x)$"
    },
    {
     "unit": 3,
     "front": "Implicit differentiation steps",
     "back": "Differentiate both sides with respect to $x$, multiply each $y$ term by $\\frac{dy}{dx}$, then solve for $\\frac{dy}{dx}$."
    },
    {
     "unit": 3,
     "front": "Derivative of an inverse function",
     "back": "If $g=f^{-1}$ and $f(a)=b$, then $g'(b)=\\frac{1}{f'(a)}$."
    },
    {
     "unit": 4,
     "front": "Position, velocity, and acceleration",
     "back": "$v=s'$, $a=v'=s''$. Speed is $|v|$. Speed increases when $v$ and $a$ have the same sign."
    },
    {
     "unit": 4,
     "front": "Linear approximation",
     "back": "$f(x)\\approx f(a)+f'(a)(x-a)$. It overestimates if $f$ is concave down and underestimates if $f$ is concave up."
    },
    {
     "unit": 4,
     "front": "Related rates: four steps",
     "back": "Draw and label the picture, write an equation relating the quantities, differentiate with respect to $t$, then substitute the known values. Substitute only after differentiating."
    },
    {
     "unit": 5,
     "front": "Mean Value Theorem",
     "back": "If $f$ is continuous on $[a,b]$ and differentiable on $(a,b)$, then $f'(c)=\\frac{f(b)-f(a)}{b-a}$ for some $c$ in $(a,b)$."
    },
    {
     "unit": 5,
     "front": "Extreme Value Theorem",
     "back": "A continuous function on a closed interval $[a,b]$ has both an absolute maximum and an absolute minimum."
    },
    {
     "unit": 5,
     "front": "First Derivative Test",
     "back": "$f'$ changes from $+$ to $-$: relative max. From $-$ to $+$: relative min. No sign change: neither."
    },
    {
     "unit": 5,
     "front": "Candidates Test (absolute extrema)",
     "back": "Evaluate $f$ at every critical point in the interval and at both endpoints. The largest value is the absolute max and the smallest is the absolute min."
    },
    {
     "unit": 6,
     "front": "Left/right sums: over or under?",
     "back": "For increasing $f$, the left sum underestimates and the right sum overestimates. For decreasing $f$, it's the reverse."
    },
    {
     "unit": 6,
     "front": "FTC Part 2",
     "back": "$\\int_a^bf(x)\\,dx=F(b)-F(a)$, where $F'=f$."
    },
    {
     "unit": 6,
     "front": "$\\int\\frac1x\\,dx$, $\\int e^x\\,dx$, $\\int\\sec^2x\\,dx$",
     "back": "$\\ln|x|+C$, $\\;e^x+C$, $\\;\\tan x+C$"
    },
    {
     "unit": 6,
     "front": "Net change theorem",
     "back": "$f(b)=f(a)+\\int_a^bf'(x)\\,dx$"
    },
    {
     "unit": 7,
     "front": "Separation of variables",
     "back": "Get all $y$ terms with $dy$ and all $x$ terms with $dx$, integrate both sides, add $+C$, use the initial condition, then solve for $y$."
    },
    {
     "unit": 7,
     "front": "Slope field",
     "back": "A short segment at each point $(x,y)$ with slope $\\frac{dy}{dx}$. Solution curves follow the segments."
    },
    {
     "unit": 8,
     "front": "Area between curves",
     "back": "$\\int_a^b(\\text{top}-\\text{bottom})\\,dx$ or $\\int_c^d(\\text{right}-\\text{left})\\,dy$"
    },
    {
     "unit": 8,
     "front": "Volume with known cross sections",
     "back": "$V=\\int_a^bA(x)\\,dx$. Squares: $A=s^2$. Semicircles: $A=\\frac{\\pi}{8}d^2$. Equilateral triangles: $A=\\frac{\\sqrt3}{4}s^2$."
    },
    {
     "unit": 8,
     "front": "Disk and washer methods",
     "back": "Disk: $\\pi\\int R^2\\,dx$. Washer: $\\pi\\int(R^2-r^2)\\,dx$. Measure radii from the axis of rotation."
    },
    {
     "unit": 8,
     "front": "Displacement vs. total distance",
     "back": "Displacement: $\\int_a^bv\\,dt$. Total distance: $\\int_a^b|v|\\,dt$."
    }
   ],
