   "flashcards": [
    {
     "unit": 1,
     "front": "When does $\\lim_{x\\to a}f(x)$ exist?",
     "back": "When both one-sided limits exist and are equal: $\\lim_{x\\to a^-}f(x)=\\lim_{x\\to a^+}f(x)$."
    },
    {
     "unit": 1,
     "front": "Three conditions for continuity at $x=a$",
     "back": "1. $f(a)$ is defined. 2. $\\lim_{x\\to a}f(x)$ exists. 3. $\\lim_{x\\to a}f(x)=f(a)$."
    },
    {
     "unit": 1,
     "front": "Intermediate Value Theorem",
     "back": "If $f$ is continuous on $[a,b]$ and $k$ is between $f(a)$ and $f(b)$, then $f(c)=k$ for some $c$ in $[a,b]$."
    },
    {
     "unit": 2,
     "front": "Limit definition of $f'(a)$",
     "back": "$f'(a)=\\lim_{h\\to0}\\frac{f(a+h)-f(a)}{h}$"
    },
    {
     "unit": 2,
     "front": "$\\frac{d}{dx}\\tan x$, $\\frac{d}{dx}\\sec x$",
     "back": "$\\sec^2x$ and $\\sec x\\tan x$"
    },
    {
     "unit": 2,
     "front": "Quotient rule",
     "back": "$\\left(\\frac{f}{g}\\right)'=\\frac{f'g-fg'}{g^2}$"
    },
    {
     "unit": 3,
     "front": "Derivative of an inverse function",
     "back": "If $g=f^{-1}$ and $f(a)=b$, then $g'(b)=\\frac{1}{f'(a)}$."
    },
    {
     "unit": 3,
     "front": "$\\frac{d}{dx}\\arctan x$, $\\frac{d}{dx}\\arcsin x$",
     "back": "$\\frac{1}{1+x^2}$ and $\\frac{1}{\\sqrt{1-x^2}}$"
    },
    {
     "unit": 4,
     "front": "L'Hospital's Rule: when can you use it?",
     "back": "Only for the indeterminate forms $\\frac00$ or $\\frac{\\pm\\infty}{\\pm\\infty}$. Then $\\lim\\frac{f}{g}=\\lim\\frac{f'}{g'}$. On FRQs, show that the form is indeterminate."
    },
    {
     "unit": 4,
     "front": "Speed is increasing when…",
     "back": "Velocity and acceleration have the same sign."
    },
    {
     "unit": 5,
     "front": "Mean Value Theorem",
     "back": "If $f$ is continuous on $[a,b]$ and differentiable on $(a,b)$, then $f'(c)=\\frac{f(b)-f(a)}{b-a}$ for some $c$ in $(a,b)$."
    },
    {
     "unit": 5,
     "front": "Second Derivative Test",
     "back": "If $f'(c)=0$ and $f''(c)>0$, there is a relative min at $c$. If $f''(c)<0$, a relative max. If $f''(c)=0$, the test is inconclusive."
    },
    {
     "unit": 5,
     "front": "Point of inflection",
     "back": "A point where $f$ is continuous and $f''$ changes sign (concavity changes). $f''=0$ alone is not enough."
    },
    {
     "unit": 6,
     "front": "FTC Part 1 (with chain rule)",
     "back": "$\\frac{d}{dx}\\int_a^{g(x)}f(t)\\,dt=f(g(x))\\,g'(x)$"
    },
    {
     "unit": 6,
     "front": "Integration by parts",
     "back": "$\\int u\\,dv=uv-\\int v\\,du$. Choose $u$ using LIATE (log, inverse trig, algebraic, trig, exponential). BC only."
    },
    {
     "unit": 6,
     "front": "Trapezoidal sum with uneven widths",
     "back": "$\\sum\\frac{f(x_{i-1})+f(x_i)}{2}\\,\\Delta x_i$. Use each subinterval's own width."
    },
    {
     "unit": 7,
     "front": "Exponential growth model",
     "back": "$\\frac{dy}{dt}=ky\\implies y=y_0e^{kt}$"
    },
    {
     "unit": 7,
     "front": "Logistic model $\\frac{dP}{dt}=kP\\left(1-\\frac{P}{L}\\right)$",
     "back": "Carrying capacity $L$. $P\\to L$ as $t\\to\\infty$ when $P_0>0$. Growth is fastest at $P=\\frac L2$. BC only."
    },
    {
     "unit": 8,
     "front": "Washer method about the $x$-axis",
     "back": "$V=\\pi\\int_a^b\\left(R(x)^2-r(x)^2\\right)dx$"
    },
    {
     "unit": 8,
     "front": "Average value of $f$ on $[a,b]$",
     "back": "$\\frac{1}{b-a}\\int_a^bf(x)\\,dx$"
    },
    {
     "unit": 9,
     "front": "Polar area",
     "back": "$A=\\frac12\\int_\\alpha^\\beta r^2\\,d\\theta$"
    },
    {
     "unit": 9,
     "front": "Parametric arc length / speed",
     "back": "Speed $=\\sqrt{\\left(\\frac{dx}{dt}\\right)^2+\\left(\\frac{dy}{dt}\\right)^2}$. Arc length $=\\int_a^b$ speed $dt$."
    },
    {
     "unit": 9,
     "front": "Polar slope $\\frac{dy}{dx}$",
     "back": "With $x=r\\cos\\theta$, $y=r\\sin\\theta$: $\\frac{dy}{dx}=\\frac{dy/d\\theta}{dx/d\\theta}$."
    },
    {
     "unit": 10,
     "front": "Geometric series $\\sum ar^n$",
     "back": "Converges to $\\frac{a}{1-r}$ (first term over $1-r$) if $|r|<1$. Diverges otherwise."
    },
    {
     "unit": 10,
     "front": "Maclaurin series for $e^x$, $\\sin x$, $\\cos x$",
     "back": "$e^x=\\sum\\frac{x^n}{n!}$, $\\sin x=\\sum\\frac{(-1)^nx^{2n+1}}{(2n+1)!}$, $\\cos x=\\sum\\frac{(-1)^nx^{2n}}{(2n)!}$"
    },
    {
     "unit": 10,
     "front": "Maclaurin series for $\\frac{1}{1-x}$ and $\\ln(1+x)$",
     "back": "$\\frac1{1-x}=\\sum x^n$ for $|x|<1$. $\\ln(1+x)=x-\\frac{x^2}2+\\frac{x^3}3-\\cdots$ for $-1<x\\le1$."
    },
    {
     "unit": 10,
     "front": "Lagrange Error Bound",
     "back": "$|R_n(x)|\\le\\frac{M}{(n+1)!}|x-a|^{n+1}$, where $M\\ge|f^{(n+1)}|$ between $a$ and $x$."
    },
    {
     "unit": 10,
     "front": "Alternating Series Error Bound",
     "back": "If the terms decrease in magnitude to $0$, then |error| $\\le$ |first omitted term|."
    },
    {
     "unit": 10,
     "front": "Ratio Test",
     "back": "$L=\\lim\\left|\\frac{a_{n+1}}{a_n}\\right|$. $L<1$: converges absolutely. $L>1$: diverges. $L=1$: inconclusive, so test endpoints another way."
    }
   ],
