   "flashcards": [
    {
     "unit": 1,
     "front": "Central vs. peripheral nervous system",
     "back": "Central: brain and spinal cord. Peripheral: everything else, divided into the somatic (voluntary) and autonomic (sympathetic for arousal, parasympathetic for calming) systems."
    },
    {
     "unit": 1,
     "front": "Action potential",
     "back": "A brief electrical charge that travels down the axon when a neuron reaches its threshold. It's all-or-none."
    },
    {
     "unit": 1,
     "front": "Key neurotransmitters",
     "back": "Dopamine (reward, movement), serotonin (mood), norepinephrine (alertness), glutamate (excitatory, memory), GABA (inhibitory), endorphins (pain relief), acetylcholine (muscle action, memory)."
    },
    {
     "unit": 1,
     "front": "Agonist vs. antagonist",
     "back": "An agonist mimics or increases a neurotransmitter's effect. An antagonist blocks it."
    },
    {
     "unit": 1,
     "front": "Limbic system structures",
     "back": "Hippocampus (forming new explicit memories), amygdala (fear and emotion), hypothalamus (hunger, thirst, body temperature, and the pituitary), thalamus (sensory relay, except smell)."
    },
    {
     "unit": 1,
     "front": "Cerebral cortex lobes",
     "back": "Frontal (planning, motor cortex), parietal (somatosensory cortex), occipital (vision), temporal (hearing, language comprehension)."
    },
    {
     "unit": 1,
     "front": "Neuroplasticity",
     "back": "The brain's ability to change its structure and function in response to experience or damage. It's greatest in childhood."
    },
    {
     "unit": 1,
     "front": "Absolute threshold vs. JND",
     "back": "Absolute threshold: the minimum stimulus detected 50% of the time. JND (difference threshold): the smallest detectable change. Weber's law says it's a constant proportion."
    },
    {
     "unit": 2,
     "front": "Bottom-up vs. top-down processing",
     "back": "Bottom-up starts from the sensory input. Top-down uses expectations, schemas, and perceptual set to interpret input."
    },
    {
     "unit": 2,
     "front": "Working memory model",
     "back": "Baddeley: a central executive coordinating a phonological loop (sounds), a visuospatial sketchpad (images), and an episodic buffer."
    },
    {
     "unit": 2,
     "front": "Explicit vs. implicit memory",
     "back": "Explicit (declarative): episodic memories (events) and semantic memories (facts). Implicit: procedural skills and classically conditioned associations."
    },
    {
     "unit": 2,
     "front": "Heuristic vs. algorithm",
     "back": "A heuristic is a fast mental shortcut that can cause errors. An algorithm is a step-by-step procedure that guarantees a solution."
    },
    {
     "unit": 2,
     "front": "Fluid vs. crystallized intelligence",
     "back": "Fluid: reasoning quickly and abstractly, which declines with age. Crystallized: accumulated knowledge and vocabulary, which is stable or increases with age."
    },
    {
     "unit": 3,
     "front": "Piaget's four stages",
     "back": "Sensorimotor (object permanence), preoperational (egocentrism, no conservation), concrete operational (conservation, logic about concrete things), formal operational (abstract reasoning)."
    },
    {
     "unit": 3,
     "front": "Vygotsky's zone of proximal development",
     "back": "The gap between what a child can do alone and what they can do with help. Scaffolding is support that is gradually removed."
    },
    {
     "unit": 3,
     "front": "Erikson's adolescent stage",
     "back": "Identity vs. role confusion. Young adults face intimacy vs. isolation."
    },
    {
     "unit": 3,
     "front": "Baumrind's parenting styles",
     "back": "Authoritarian (demanding, cold), permissive (warm, few rules), authoritative (warm with clear expectations, linked to the best outcomes), neglectful."
    },
    {
     "unit": 3,
     "front": "Classical conditioning terms",
     "back": "An unconditioned stimulus (US) causes an unconditioned response (UR). A neutral stimulus paired with the US becomes a conditioned stimulus (CS) that causes a conditioned response (CR)."
    },
    {
     "unit": 3,
     "front": "Reinforcement vs. punishment; positive vs. negative",
     "back": "Reinforcement increases a behavior and punishment decreases it. Positive means something is added and negative means something is removed."
    },
    {
     "unit": 3,
     "front": "Reinforcement schedules",
     "back": "Fixed ratio (after N responses), variable ratio (after an unpredictable number, most resistant to extinction), fixed interval (after a set time), variable interval (after an unpredictable time)."
    },
    {
     "unit": 4,
     "front": "Fundamental attribution error",
     "back": "Overestimating someone's disposition and underestimating the situation when explaining other people's behavior."
    },
    {
     "unit": 4,
     "front": "Asch vs. Milgram",
     "back": "Asch studied conformity (going along with a group on line-length judgments). Milgram studied obedience to authority (\"shocks\" ordered by an experimenter)."
    },
    {
     "unit": 4,
     "front": "Elaboration likelihood model",
     "back": "The central route persuades with strong arguments and leads to lasting change. The peripheral route uses cues like attractiveness or celebrity and leads to brief change."
    },
    {
     "unit": 4,
     "front": "Big Five traits (OCEAN)",
     "back": "Openness, conscientiousness, extraversion, agreeableness, neuroticism (emotional stability)."
    },
    {
     "unit": 4,
     "front": "Self-efficacy and reciprocal determinism",
     "back": "Bandura. Self-efficacy is belief in your ability to succeed. Reciprocal determinism is the two-way interaction of behavior, thoughts, and environment."
    },
    {
     "unit": 4,
     "front": "Maslow's hierarchy of needs",
     "back": "Physiological, safety, belongingness and love, esteem, self-actualization."
    },
    {
     "unit": 5,
     "front": "Diathesis–stress model",
     "back": "A predisposition (diathesis) plus environmental stress produces a disorder."
    },
    {
     "unit": 5,
     "front": "Problem-focused vs. emotion-focused coping",
     "back": "Problem-focused changes the stressor itself. Emotion-focused manages your emotional reaction to it."
    },
    {
     "unit": 5,
     "front": "Cognitive behavioral therapy (CBT)",
     "back": "Combines changing distorted thinking (cognitive therapy, as in Beck's work) with changing behavior. It's evidence-based for depression and anxiety."
    },
    {
     "unit": 5,
     "front": "Biomedical treatments",
     "back": "SSRIs (depression, anxiety), antipsychotics (schizophrenia), lithium (bipolar disorder), ECT (severe depression that doesn't respond to other treatment)."
    }
   ],
